import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"MCP control layer","description":"","frontmatter":{},"headers":[],"relativePath":"mcp.md","filePath":"mcp.md"}'),i={name:"mcp.md"};function n(s,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="mcp-control-layer" tabindex="-1">MCP control layer <a class="header-anchor" href="#mcp-control-layer" aria-label="Permalink to &quot;MCP control layer&quot;">​</a></h1><p>DockPilot exposes a Model Context Protocol server so an external AI agent can read real DockPilot state and request narrowly scoped changes.</p><h2 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;Transport&quot;">​</a></h2><p>The MCP endpoint is a stateless <strong>Streamable HTTP</strong> endpoint that accepts <code>POST</code>, <code>GET</code>, and <code>DELETE</code> at <code>/api/v1/mcp</code> and answers with JSON responses. It is registered only when <code>MCP_ENABLED</code> is not <code>false</code>.</p><p>For local development, an optional <strong>stdio</strong> entry point is available. It authenticates once at startup from an environment variable and speaks MCP over stdin/stdout, logging only to stderr.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>External agents never reuse an administrator&#39;s browser session. They authenticate with a dedicated <strong>AI credential</strong>.</p><ul><li>Tokens are 32 random bytes rendered as <code>dpai_</code> followed by 43 URL-safe characters.</li><li>The raw token is returned <strong>exactly once</strong>, in the create response. It is never stored in plaintext and never returned by any other endpoint.</li><li>Only an HMAC-SHA256 digest is persisted, keyed by <code>MCP_TOKEN_SECRET</code>. In non-production the key falls back to a value derived from <code>SESSION_SECRET</code>. <strong>Production refuses to start while MCP is enabled and <code>MCP_TOKEN_SECRET</code> is missing.</strong></li><li>Credentials carry a name, an optional description, an optional agent identity, a permission level, an optional expiry of 1 to 365 days, an optional metadata object, a token prefix for identification, and <code>createdAt</code>, <code>lastUsedAt</code>, <code>revokedAt</code>, and <code>disabledAt</code> timestamps.</li><li>Credentials are revoked by an administrator and rejected immediately afterward. Unknown, malformed, revoked, disabled, and expired tokens all fail authentication.</li></ul><p><code>GET /api/v1/mcp</code> and <code>DELETE /api/v1/mcp</code> run the same credential check before the transport answers the request, so a probe can never bypass authentication.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Permissions are ordered <code>read</code>, <code>write</code>, <code>destructive</code> from least to most privileged. They are enforced on the server for every tool call using the stored permission level of the authenticated credential. A credential can never raise its own permission level. No tool accepts a permission, role, or scope as input.</p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><ul><li><code>dockpilot_health</code> — <strong>read</strong>. Reports API availability, the MCP contract version, and live database reachability.</li><li><code>dockpilot_system_status</code> — <strong>read</strong>. Returns organization-scoped counts for users, active sessions, AI credentials, pending approvals, and 24-hour audit volume.</li><li><code>dockpilot_list_users</code> — <strong>read</strong>. Lists organization users with bounded, keyset-paginated pages.</li><li><code>dockpilot_list_sessions</code> — <strong>read</strong>. Lists browser sessions belonging to organization users.</li><li><code>dockpilot_list_ai_credentials</code> — <strong>read</strong>. Lists AI credentials. Raw tokens are never returned.</li><li><code>dockpilot_list_audit_events</code> — <strong>read</strong>. Filters and pages audit events. Event summaries are redacted.</li><li><code>dockpilot_get_audit_event</code> — <strong>read</strong>. Returns a single redacted audit event.</li><li><code>dockpilot_list_approvals</code> — <strong>read</strong>. Lists approval requests, optionally filtered by status.</li><li><code>dockpilot_update_my_credential</code> — <strong>write</strong>. Updates only the calling credential&#39;s description, agent identity, and metadata.</li><li><code>dockpilot_request_session_revocation</code> — <strong>destructive</strong>. Creates a pending approval to revoke a browser session. Requires a written justification.</li><li><code>dockpilot_request_credential_revocation</code> — <strong>destructive</strong>. Creates a pending approval to revoke an AI credential. Requires a written justification.</li></ul><p>Tool metadata lives in one place, <code>packages/shared/src/mcp.ts</code>, so the shared contract and the API tool registry cannot disagree about permission level, rate category, or action name. Every tool advertises a strict JSON Schema with <code>additionalProperties: false</code>, and inputs are re-validated strictly on the server before any handler runs.</p><p>There is <strong>no shell execution tool, no arbitrary SQL tool, no Docker socket access, and no generic &quot;execute anything&quot; tool</strong>.</p><h2 id="rate-limiting" tabindex="-1">Rate limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate limiting&quot;">​</a></h2><p>In addition to the global per-IP API limit, MCP requests are limited per credential with fixed windows:</p><ul><li><strong>read</strong> — 120 requests per minute.</li><li><strong>write</strong> — 20 requests per minute.</li><li><strong>destructive</strong> — 5 requests per 5 minutes.</li></ul><p>Authentication attempts are limited separately to 20 per minute per client address, so credential guessing is throttled before it reaches the database.</p><h2 id="human-approval-for-destructive-work" tabindex="-1">Human approval for destructive work <a class="header-anchor" href="#human-approval-for-destructive-work" aria-label="Permalink to &quot;Human approval for destructive work&quot;">​</a></h2><p>The two destructive tools never perform the action they describe. They create a pending approval request that records the requesting credential, agent identity, tool, action type, target, and justification, and expires one hour after creation. An administrator then approves or rejects it.</p><p>Only on approval does DockPilot execute the action, inside a single database transaction that locks the approval row and writes the execution audit event. Rejected, expired, and already-decided requests cannot execute anything. Approving a request whose target has disappeared results in a recorded <code>failed</code> approval instead of a silent success. The executable action types are currently <code>session.revoke</code> and <code>ai_credential.revoke</code>. Any other action type is refused.</p><p>Read-only tools never require approval.</p><h2 id="audit-logging" tabindex="-1">Audit logging <a class="header-anchor" href="#audit-logging" aria-label="Permalink to &quot;Audit logging&quot;">​</a></h2><p>Every MCP tool call produces an audit event, including calls that fail before any work happens: unknown tools, invalid input, insufficient permission, rate-limited attempts, and internal failures. Each event records the correlation ID, the AI credential ID and agent identity, the tool name, the action, the permission used, the target, a sanitized input summary, a result summary, the outcome, an error category, and the duration in milliseconds. Administrator-initiated credential and approval changes are audited with the administrator&#39;s user ID.</p><p>Key behaviors:</p><ul><li><strong>Append-only by construction.</strong> A PostgreSQL trigger rejects <code>UPDATE</code> and <code>DELETE</code> on <code>audit_logs</code>, so no application path can rewrite or erase history.</li><li><strong>Fail closed.</strong> For mutating tools, the business write and the audit insert commit in the same transaction. If the audit record cannot be persisted, the change is rolled back and the tool returns an error.</li><li><strong>Redacted before storage.</strong> Values whose keys match patterns like password, secret, token, authorization, cookie, API key, private key, credential, hash, signature, or session are replaced with <code>[REDACTED]</code>. Payloads are capped at 4096 bytes, nested five levels deep, 20 array items, and 512 characters per string. Raw tool responses are not stored; array results are recorded as counts.</li><li><strong>Correlation IDs.</strong> A valid <code>X-Correlation-Id</code> request header is reused if it matches the expected shape; otherwise DockPilot generates one. The value is written to the audit event and echoed back on the response.</li></ul>',27)])])}const g=t(i,[["render",n]]);export{h as __pageData,g as default};
